	@Test
	void cacheIdentityIncludesLookupRevisionAndDetachedRowsKeepTheirOldSpelling() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		AtomicReference<Object> revision = new AtomicReference<>(new Object());
		AtomicReference<String> spelling = new AtomicReference<>("old-blank-node");
		AtomicInteger reads = new AtomicInteger();
		when(source.idSpace()).thenReturn(new Object());
		when(source.valueLookupScope()).thenAnswer(ignored -> revision.get());
		doAnswer(ignored -> {
			reads.incrementAndGet();
			return blankNodeRecord(spelling.get());
		}).when(source).recordView(42);
		NativeResultEncoder encoder = new NativeResultEncoder();
		NativeEncodedBindingSet first = encoder.encode(row(source));
		NativeEncodedBindingSet repeated = encoder.encode(row(source));
		assertSame(first.getValueScope(), repeated.getValueScope());
		assertSame(first.getEncodedValue(0), repeated.getEncodedValue(0));
		assertEquals(1, reads.get());

		revision.set(new Object());
		spelling.set("replacement-blank-node");
		NativeEncodedBindingSet replacement = encoder.encode(row(source));
		assertNotSame(first.getValueScope(), replacement.getValueScope());
		assertEquals(2, reads.get());
		encoder.clear();
		assertEquals(SimpleValueFactory.getInstance().createBNode("old-blank-node"), first.getValue(0));
		assertEquals(SimpleValueFactory.getInstance().createBNode("replacement-blank-node"), replacement.getValue(0));
	}

	@Test
	void revisionChangingDuringLookupRejectsTheTentativeRowAndItsCache() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		AtomicReference<Object> revision = new AtomicReference<>(new Object());
		AtomicBoolean change = new AtomicBoolean(true);
		when(source.idSpace()).thenReturn(new Object());
		when(source.valueLookupScope()).thenAnswer(ignored -> revision.get());
		doAnswer(ignored -> {
			if (change.getAndSet(false)) {
				revision.set(new Object());
				return blankNodeRecord("old");
			}
			return blankNodeRecord("new");
		}).when(source).recordView(42);
		NativeResultEncoder encoder = new NativeResultEncoder();
		assertNull(encoder.encode(row(source)), "A changed native scope must fall back before the row escapes");
		NativeEncodedBindingSet current = encoder.encode(row(source));
		assertEquals(SimpleValueFactory.getInstance().createBNode("new"), current.getValue(0));
	}

