	@Test
	void retainedCacheFindsNonconsecutiveReuseAcrossProbeWindows() {
		ProbeSource source = new ProbeSource();
		NativeResultEncoder encoder = new NativeResultEncoder();
		encodeUniqueWindow(encoder, source);
		assertPausedWithoutReads(encoder, source);
		// A 64-term cycle presents different halves in successive 32-row samples, separated by 256 skipped rows.
		for (int half = 0; half < 2; half++) {
			for (int index = 0; index < 32; index++) {
				assertNotNull(encoder.encode(row(source.source, 5000 + 32 * half + index)));
			}
			assertPausedWithoutReads(encoder, source);
		}
		for (int index = 0; index < 64; index++) {
			assertNotNull(encoder.encode(row(source.source, 5000 + index)),
					"Probe windows must retain their bounded descriptor cache to discover longer reuse cycles");
		}
	}

