	private static ValueStoreRecordView blankNodeRecord(String label) {
		byte[] lexical = label.getBytes(StandardCharsets.UTF_8);
		byte[] record = new byte[lexical.length + 1];
		record[0] = 2;
		System.arraycopy(lexical, 0, record, 1, lexical.length);
		return ValueStoreRecordView.takeOwnership(record);
	}
